<?php
require_once __DIR__.'/includes/auth.php';$u=require_role('customer');$pg=pagination_window(24,48);release_session_lock();
$sql="SELECT f.created_at,u.id,u.name,u.role,u.profile_image,u.city,u.area,p.headline,p.verification_status provider_verified,b.business_name,b.logo,b.verification_status business_verified FROM favorites f JOIN users u ON u.id=f.target_user_id LEFT JOIN provider_profiles p ON p.user_id=u.id LEFT JOIN business_profiles b ON b.user_id=u.id WHERE f.customer_id=? AND u.status='active' ORDER BY f.created_at DESC,f.id DESC LIMIT ".($pg['per']+1)." OFFSET ".$pg['offset'];
$q=db()->prepare($sql);$q->execute([(int)$u['id']]);$items=$q->fetchAll();$hasNext=trim_page_results($items,$pg['per']);$pageTitle='Favorites — LocalConnect';require __DIR__.'/includes/header.php';?>
<div class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><h1 class="fw-bold mb-0">Favorite Providers</h1><a class="btn btn-primary" href="<?=e(base_url('search.php'))?>">Browse Services</a></div><div class="row g-4"><?php foreach($items as $x):$isBiz=$x['role']==='business';$name=$isBiz?($x['business_name']?:$x['name']):$x['name'];$img=$isBiz?$x['logo']:$x['profile_image'];?><div class="col-md-6 col-lg-4"><div class="soft-card p-4 h-100"><img class="profile-hero mb-3" src="<?=e($img?base_url($img):base_url('assets/images/avatar-placeholder.svg'))?>" alt=""><h5><?=e($name)?></h5><div class="text-muted small mb-3"><?=e(trim(($x['area']??'').' '.($x['city']??'')))?></div><a class="btn btn-outline-primary" href="<?=e(base_url(($isBiz?'business':'provider').'.php?id='.$x['id']))?>">View Profile</a><button class="btn btn-outline-danger js-favorite ms-1" data-target="<?=$x['id']?>">Remove</button></div></div><?php endforeach;?><?php if(!$items):?><div class="col-12"><div class="soft-card p-5 text-center"><h4>No favorite providers on this page.</h4><p class="text-muted">Save providers and businesses you may want to contact later.</p><a class="btn btn-primary" href="<?=e(base_url('search.php'))?>">Browse Services</a></div></div><?php endif;?></div><?=pagination_nav($pg['page'],$hasNext)?></div><?php require __DIR__.'/includes/footer.php';?>
